mapper.select:
select * from tb_user
where 1=1

    and phone like concat('%',#{search},'%')


    and user_name like concat('%',#{userName},'%')


    and sex=#{sex}


    and divide_scale != 0


    and platform=#{platform}


    and sys_phone=#{sysPhone}


    and status=#{status}

order by create_time desc

select count(*)
from tb_user
where inviter_code = #{inviterCode}

mapper.update:
update tb_user
set cash_deposit = cash_deposit + #{cashDeposit}
where user_id = #{userId}

update user_money set

    money = money+#{money}


    money = money-#{money}

where user_id = #{userId}
